    removed = []
    for n in sorted_nodes:
        if not n['removable']:
            continue
        if n['depth'] == 0:
            continue
        if any(c in retained for c in children[n['id']]):
            continue
        sym = n['symbol']
        if sym in required_symbols and symbol_count[sym] == 1:
            continue
        retained.discard(n['id'])
        removed.append(n['id'])
        symbol_count[sym] -= 1
    retained_sorted = sorted(retained)
    return {"removed_node_ids": removed, "retained_node_ids": retained_sorted}
